import numpy as np

def compute_order_amount(on_hand_inventory, pipeline_orders, last_demand, quoted_lead_time):
    base_target = 200.0  # OPT_PARAM: {"initial": 200.0, "min": 200.0, "max": 350.0, "type": "float"}
    demand_response = 0.8  # OPT_PARAM: {"initial": 0.8, "min": 0.8, "max": 1.1, "type": "float"}
    adjustment_factor = 0.2  # OPT_PARAM: {"initial": 0.2, "min": 0.2, "max": 0.5, "type": "float"}
    pipeline_weight = 0.5  # OPT_PARAM: {"initial": 0.5, "min": 0.5, "max": 1.0, "type": "float"}

    demand_adjustment = demand_response * last_demand
    target = base_target + demand_adjustment
    pipeline_sum = pipeline_weight * sum(pipeline_orders[:5])
    order_amount = max(0.0, adjustment_factor * (target - on_hand_inventory - pipeline_sum))
    return order_amount
